  const m = item.json;
  const headers = (m.payload && m.payload.headers) || [];
  const h = (name) => (headers.find(x => x.name && x.name.toLowerCase() === name.toLowerCase()) || {}).value || '';
  const subject = h('Subject');
  const from = h('From');
  const body = stripHtml(m.snippet || m.text || '');
  const link = '';
  const title = subject;
  out.push({ json: {
    source_channel: 'email',
    source_id: 'SRC-004',
    source_url: '',
    canonical_url: '',
