const crypto = require('crypto');
const out = [];
for (const item of $input.all()) {
  const llmRaw = item.json.content && item.json.content[0] && item.json.content[0].text || '{}';
  let ext = {};
  try { ext = JSON.parse(llmRaw.replace(/^```json|```$/g, '').trim()); } catch { ext = {}; }
  const raw = $('Build raw_id').item.json;
  const title = (ext.headline_normalized || raw.title_raw || '').toLowerCase();
  const summary = (ext.summary_normalized || raw.excerpt_raw || '').toLowerCase();
  const text = title + ' ' + summary;

  const impactMap = { low: 5, medium: 11, high: 16, critical: 20 };
  const impact_score = impactMap[ext.impact_level] || 8;

  const ageDays = (Date.now() - new Date(raw.source_published_at).getTime()) / 86400000;
  const freshness_score = ageDays < 3 ? 15 : ageDays < 7 ? 12 : ageDays < 14 ? 8 : 3;

  const schoolsKeywords = ['wordpress','plugin','freelance','createur','formateur','lms','crm','seo','automatisation','kadence','fluent','tutor','elementor','woocommerce'];
  const audience_fit_score = Math.min(20, schoolsKeywords.filter(k => text.includes(k)).length * 4);

  const actionVerbs = ['tester','mettre a jour','mettre à jour','activer','configurer','installer','reduire','economiser','ameliorer','améliorer'];
  const actionability_score = Math.min(15, actionVerbs.filter(v => text.includes(v)).length * 5);

  const novelty_score = (ext.event_type === 'major_release' || ext.event_type === 'launch') ? 8 : 5;

  const business_value_score = ext.offer_type && ext.offer_type !== 'null' ? 8 : (ext.event_type === 'partnership' ? 6 : 3);

  const pedagogical_value_score = ext.event_type === 'tutorial_resource' ? 9 : (Array.isArray(ext.key_points) && ext.key_points.length >= 3 ? 6 : 3);

  const noiseMarkers = ['excited to announce','game-changer','revolutionary','unprecedented'];
  const noise_penalty = -Math.min(20, noiseMarkers.filter(n => text.includes(n)).length * 8);

  const cluster_key = crypto.createHash('sha1').update(`${(ext.primary_product||'').toLowerCase()}|${ext.version_detected||''}|${ext.event_type||''}`).digest('hex');

  const editorial_score = impact_score + freshness_score + audience_fit_score + actionability_score + novelty_score + business_value_score + pedagogical_value_score + noise_penalty;

  let status_editorial = 'rejected', reason_rejected = 'score_too_low';
  if (editorial_score >= 65) { status_editorial = 'candidate'; reason_rejected = ''; }
  else if (editorial_score >= 50) { status_editorial = 'backlog'; reason_rejected = ''; }

  const item_id = `ITEM-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${cluster_key.slice(0,6)}`;

  out.push({ json: {
    item_id, cluster_key,
    raw_id: raw.raw_id,
    primary_brand: ext.primary_brand || raw.brand_name || '',
    primary_product: ext.primary_product || '',
    version_detected: ext.version_detected || '',
    event_type: ext.event_type || 'ecosystem_news',
    impact_level: ext.impact_level || 'low',
    release_date: raw.source_published_at,
    first_seen_at: raw.ingested_at,
    last_seen_at: raw.ingested_at,
    headline_normalized: ext.headline_normalized || raw.title_raw,
    summary_normalized: ext.summary_normalized || raw.excerpt_raw,
    key_points: Array.isArray(ext.key_points) ? ext.key_points.join(';') : '',
    offer_type: ext.offer_type && ext.offer_type !== 'null' ? ext.offer_type : '',
    offer_deadline: ext.offer_deadline && ext.offer_deadline !== 'null' ? ext.offer_deadline : '',
    links_primary: raw.canonical_url,
    source_count: 1,
    impact_score, freshness_score, audience_fit_score, actionability_score,
    novelty_score, business_value_score, pedagogical_value_score, noise_penalty,
    editorial_score, confidence_score: 0.8,
    status_editorial, reason_rejected
  }});
}
return out;
